// lib/webfetcher.js
const axios = require('axios');
const cheerio = require('cheerio');

const USER_AGENT = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36';

async function fetchPage(url) {
  const { data } = await axios.get(url, {
    headers: { 'User-Agent': USER_AGENT },
    timeout: 10000
  });
  return data;
}

function parseMeta(html) {
  const $ = cheerio.load(html);
  return {
    title: $('title').text().trim(),
    description: $('meta[name="description"]').attr('content') || '',
    ogImage: $('meta[property="og:image"]').attr('content') || '',
    canonical: $('link[rel="canonical"]').attr('href') || '',
  };
}

function extractLinks(html, baseUrl) {
  const $ = cheerio.load(html);
  const links = [];
  $('a[href]').each((i, el) => {
    const href = $(el).attr('href');
    const text = $(el).text().trim();
    if (href && !href.startsWith('#') && !href.startsWith('javascript:')) {
      links.push({ text: text || '[link]', href });
    }
  });
  return links;
}

async function scrape(url) {
  const html = await fetchPage(url);
  return {
    url,
    meta: parseMeta(html),
    links: extractLinks(html, url),
    totalLinks: extractLinks(html, url).length,
  };
}

module.exports = { scrape, fetchPage, parseMeta, extractLinks };

// lib/anichin.js — simplified version for example
const cloudscraper = require('cloudscraper');
const cheerio = require('cheerio');

const BASE_URL = 'https://anichin.cafe';
const HEADERS = {
  'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36',
  'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
  'Accept-Language': 'id-ID,id;q=0.9,en-US;q=0.8,en;q=0.7',
  'Referer': BASE_URL + '/',
};

async function getLatest() {
  const html = await cloudscraper.get({ uri: BASE_URL + '/', headers: HEADERS });
  const $ = cheerio.load(html);
  const results = [];

  $('.latesthome').next('.listupd').find('article.bs').each((i, el) => {
    results.push({
      title: $(el).find('.tt').text().trim(),
      episode: $(el).find('.epx').text().trim(),
      thumbnail: $(el).find('img').attr('src'),
      url: $(el).find('a').attr('href'),
    });
  });

  return results;
}

module.exports = { getLatest };

