implementation.code:
// lib/instagram.js
const axios = require('axios');

const API_BASE = 'https://www.instagram.com/api/v1';
const USER_AGENT = 'Mozilla/5.0 (Linux; Android 10; SM-G973F) AppleWebKit/537.36';

async function getMediaInfo(mediaId) {
  const { data } = await axios.get(`${API_BASE}/media/${mediaId}/info/`, {
    headers: {
      'User-Agent': USER_AGENT,
      'x-ig-app-id': '936619743392459',
      'Referer': 'https://www.instagram.com/',
      'Accept': '*/*',
    }
  });
  return data;
}

async function getUserMedia(username) {
  const { data } = await axios.get(`${API_BASE}/users/web_profile_info/`, {
    params: { username },
    headers: {
      'User-Agent': USER_AGENT,
      'x-ig-app-id': '936619743392459',
      'Referer': 'https://www.instagram.com/',
    }
  });
  return data;
}

module.exports = { getMediaInfo, getUserMedia };

// lib/fbdl.js
const axios = require('axios');
const FormData = require('form-data');
const vm = require('vm');

async function download(url) {
  const form = new FormData();
  form.append('url', url);

  const { data } = await axios.post('https://fsave.io/action.php?lang=id', form, {
    headers: {
      ...form.getHeaders(),
      'User-Agent': 'Mozilla/5.0 (Linux; Android 10) AppleWebKit/537.36',
      'Referer': 'https://fsave.io/id',
      'Origin': 'https://fsave.io',
    }
  });

  // Deobfuscate JavaScript
  const context = vm.createContext({
    window: { location: { hostname: 'fsave.io' } },
    document: { getElementById: () => ({ innerHTML: '' }) },
    location: { hostname: 'fsave.io' }
  });

  const decoded = vm.runInContext(data, context);
  const cleanHtml = decoded.replace(/\\"/g, '"').replace(/\\/g, '');

  // Ekstrak download URL dari HTML
  const hd = cleanHtml.match(/<a href="([^"]+)"[^>]+title="Download HD"/i);
  const sd = cleanHtml.match(/<a href="([^"]+)"[^>]+title="Download SD"/i);

  return {
    video_hd: hd ? hd[1] : null,
    video_sd: sd ? sd[1] : null,
  };
}

module.exports = { download };
